#### Solution 1: Using `call` Function
```javascript
const call = (phoneNumber, message) => {
  return new Promise((resolve, reject) => {
    const audio = new Audio('https://www.soundhelix.com/examples/audio/mp3-preview.mp3');
    audio.play().then(() => {
      navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
        const mediaRecorder = new MediaRecorder(stream);
        mediaRecorder.start();
        mediaRecorder.onstop = () => {
          const blob = mediaRecorder.getBlob('recording-' + Date.now() + '.mp3');
          const url = URL.createObjectURL(blob);
          const a = document.createElement('audio');
          a.src = url;
          a.onloadstart = () => {
            const reader = new FileReader();
            reader.onloadend = () => {
              const file = new Blob(reader.result.split('\n'), { type: 'audio/mpeg' });
              resolve(file);
            };
            reader.readAsDataURL(reader.result);
          };
        };
      });
    });
  });
};

